from rest_framework.decorators import api_view, permission_classes
from rest_framework.permissions import IsAuthenticated
from rest_framework.response import Response
from rest_framework import status
from rest_framework.exceptions import PermissionDenied
from django.shortcuts import get_object_or_404
from .models import ModerationFlag

@api_view(['POST'])
@permission_classes([IsAuthenticated])
def dismiss_moderation_flag(request, flag_id):
    flag = get_object_or_404(ModerationFlag, id=flag_id)
    target = flag.content_object
    if not (request.user.is_staff or (hasattr(target, 'community') and target.community.is_moderator(request.user))):
        raise PermissionDenied("You are not a moderator for the target entity's community.")

    if flag.status == 'DISMISSED':
        return Response({'message': 'Flag already dismissed'}, status=status.HTTP_200_OK)

    flag.status = 'DISMISSED'
    flag.dismissed_by = request.user
    flag.save(update_fields=['status', 'dismissed_by'])
    return Response({'status': 'dismissed', 'flag_id': flag.id})
